describe('validateSignature — bit-for-bit port of classes/LineAPI.php:959-963', () => {
  it.each(PHP_CROSS_CHECKED_SIGNATURES)(
    'accepts the PHP-computed signature: $label',
    ({ body, secret, expectedSignature }) => {
      expect(validateSignature(body, expectedSignature, secret)).toBe(true);
    }
  );

  it.each(PHP_CROSS_CHECKED_SIGNATURES)(
    'rejects a tampered signature (last char flipped): $label',
    ({ body, secret, expectedSignature }) => {
      const lastChar = expectedSignature.slice(-1);
      const tampered = expectedSignature.slice(0, -1) + (lastChar === 'A' ? 'B' : 'A');
      expect(validateSignature(body, tampered, secret)).toBe(false);
    }
  );

  it.each(PHP_CROSS_CHECKED_SIGNATURES)(
    'rejects a tampered body: $label',
    ({ body, secret, expectedSignature }) => {
      expect(validateSignature(`${body}X`, expectedSignature, secret)).toBe(false);
    }
  );

  it.each(PHP_CROSS_CHECKED_SIGNATURES)(
    'rejects the wrong channel secret: $label',
    ({ body, expectedSignature }) => {
      expect(validateSignature(body, expectedSignature, 'definitely-the-wrong-secret')).toBe(false);
    }
  );

  it('rejects an empty signature without throwing', () => {
    const fixture = PHP_CROSS_CHECKED_SIGNATURES[0]!;
    expect(() => validateSignature(fixture.body, '', fixture.secret)).not.toThrow();
    expect(validateSignature(fixture.body, '', fixture.secret)).toBe(false);
  });

  it('rejects non-base64 garbage signatures without throwing', () => {
    const fixture = PHP_CROSS_CHECKED_SIGNATURES[0]!;
    const garbageInputs = [
      'not-base64-at-all!!!',
      '<<<>>>???',
      '␀control-bytes',
      'ก ข ค ง แ ไทย ไม่ใช่ base64',
      '   ',
      'null',
    ];
    for (const garbage of garbageInputs) {
      expect(() => validateSignature(fixture.body, garbage, fixture.secret)).not.toThrow();
      expect(validateSignature(fixture.body, garbage, fixture.secret)).toBe(false);
    }
  });

  it('rejects length-mismatched signatures without throwing — the naive crypto.timingSafeEqual bug this must not have', () => {
    const fixture = PHP_CROSS_CHECKED_SIGNATURES[0]!;
    // A direct `crypto.timingSafeEqual(Buffer.from(expected), Buffer.from(signature))` port would
    // throw `RangeError: Input buffers must have the same byte length` for every input below.
    const lengthMismatchedSignatures = [
      'a',
      'ab',
      fixture.expectedSignature.slice(0, 10),
      fixture.expectedSignature.slice(0, 43), // one byte short of the real 44-char base64 output
      `${fixture.expectedSignature}extra`,
      `${fixture.expectedSignature}=`, // one byte over
      'x'.repeat(1000),
    ];
    for (const signature of lengthMismatchedSignatures) {
      expect(() => validateSignature(fixture.body, signature, fixture.secret)).not.toThrow();
      expect(validateSignature(fixture.body, signature, fixture.secret)).toBe(false);
    }
  });

  it('accepts a Buffer body identically to the equivalent UTF-8 string body', () => {
    const fixture = PHP_CROSS_CHECKED_SIGNATURES[0]!;
    expect(
      validateSignature(Buffer.from(fixture.body, 'utf8'), fixture.expectedSignature, fixture.secret)
    ).toBe(true);
  });

  it('a Thai-text body signs identically whether passed as a string or its UTF-8 Buffer', () => {
    const fixture = PHP_CROSS_CHECKED_SIGNATURES.find((f) => f.label === 'thai text body')!;
    expect(
      validateSignature(Buffer.from(fixture.body, 'utf8'), fixture.expectedSignature, fixture.secret)
    ).toBe(true);
  });
});

