/** Records every call made through the injected transport; never touches a real socket. */
function createFetchMock(responses: Array<{ status: number; body: unknown }>): {
  fetchImpl: LineFetch;
  calls: Array<{ url: string; init: LineHttpRequestInit }>;
} {
  const calls: Array<{ url: string; init: LineHttpRequestInit }> = [];
  let callIndex = 0;
  const fetchImpl: LineFetch = async (url, init) => {
    calls.push({ url, init });
    const response = responses[Math.min(callIndex, responses.length - 1)];
    callIndex += 1;
    if (!response) {
      throw new Error('createFetchMock: no response configured for this call');
    }
    return {
      status: response.status,
      json: async () => response.body,
    };
  };
  return { fetchImpl, calls };
}

/** Formats a Date as a bare "YYYY-MM-DD HH:MM:SS" Asia/Bangkok wall-clock string — the same
 * shape `users.reply_token_expires` (a MySQL DATETIME, no offset) actually has in the DB. */
function toBangkokDatetimeString(date: Date): string {
  const parts = new Intl.DateTimeFormat('en-CA', {
    timeZone: 'Asia/Bangkok',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    hour12: false,
  }).formatToParts(date);
  const get = (type: string): string => parts.find((p) => p.type === type)?.value ?? '00';
  return `${get('year')}-${get('month')}-${get('day')} ${get('hour')}:${get('minute')}:${get('second')}`;
}

function futureBangkokDatetime(msFromNow: number): string {
  return toBangkokDatetimeString(new Date(Date.now() + msFromNow));
}

function pastBangkokDatetime(msAgo: number): string {
  return toBangkokDatetimeString(new Date(Date.now() - msAgo));
}

const BASE_OPTIONS: Omit<LineApiOptions, 'fetchImpl'> = { channelAccessToken: 'test-channel-access-token' };

describe('sendMessage — reply-token-first / push-fallback dispatcher', () => {
  // Safety net: if the implementation ever bypasses the injected fetchImpl mock and falls
  // through to the real transport (defaultFetch -> global fetch), this guard throws instead of
  // silently letting a real network call happen — every test in this block fails loudly if the
  // mock is bypassed, per the acceptance criteria.
  let guardHits: number;
  beforeEach(() => {
    guardHits = 0;
    vi.stubGlobal('fetch', async () => {
      guardHits += 1;
      throw new Error(
        '[test guard] global fetch was invoked directly — every LINE API call must go through the injected fetchImpl mock, not the real transport'
      );
    });
  });
  afterEach(() => {
    vi.unstubAllGlobals();
  });

  it('reply-success (HTTP 200) never calls push', async () => {
    const { fetchImpl, calls } = createFetchMock([{ status: 200, body: { sentMessages: [{ id: '1' }] } }]);
    const onReplyTokenUsed = vi.fn();

    const result = await sendMessage(
      {
        userId: 'Uabc123',
        messages: 'สวัสดีครับ',
        replyToken: 'reply-token-live',
        tokenExpires: futureBangkokDatetime(5 * 60_000),
        internalUserId: 42,
        onReplyTokenUsed,
      },
      { ...BASE_OPTIONS, fetchImpl }
    );

    expect(calls).toHaveLength(1);
    expect(calls[0]!.url).toBe('https://api.line.me/v2/bot/message/reply');
    expect(result).toEqual({ code: 200, body: { sentMessages: [{ id: '1' }] }, method: 'reply' });
    expect(guardHits).toBe(0);
  });

  it('reply-fail (non-200) falls back to push, called strictly after reply', async () => {
    const { fetchImpl, calls } = createFetchMock([
      { status: 400, body: { message: 'Invalid reply token' } },
      { status: 200, body: { sentMessages: [{ id: '2' }] } },
    ]);

    const result = await sendMessage(
      {
        userId: 'Uabc123',
        messages: 'hi',
        replyToken: 'reply-token-live',
        tokenExpires: futureBangkokDatetime(5 * 60_000),
      },
      { ...BASE_OPTIONS, fetchImpl }
    );

    expect(calls).toHaveLength(2);
    expect(calls[0]!.url).toBe('https://api.line.me/v2/bot/message/reply');
    expect(calls[1]!.url).toBe('https://api.line.me/v2/bot/message/push');
    expect(result).toEqual({ code: 200, body: { sentMessages: [{ id: '2' }] }, method: 'push' });
    expect(guardHits).toBe(0);
  });

  it('expired token calls push only — reply is never attempted', async () => {
    const { fetchImpl, calls } = createFetchMock([{ status: 200, body: { sentMessages: [] } }]);

    const result = await sendMessage(
      {
        userId: 'Uabc123',
        messages: 'hi',
        replyToken: 'reply-token-expired',
        tokenExpires: pastBangkokDatetime(60_000),
      },
      { ...BASE_OPTIONS, fetchImpl }
    );

    expect(calls).toHaveLength(1);
    expect(calls[0]!.url).toBe('https://api.line.me/v2/bot/message/push');
    expect(result.method).toBe('push');
    expect(guardHits).toBe(0);
  });

  it.each([undefined, null, ''] as const)('no reply token (%s) sends push directly', async (replyToken) => {
    const { fetchImpl, calls } = createFetchMock([{ status: 200, body: {} }]);

    const result = await sendMessage(
      { userId: 'Uabc123', messages: 'hi', replyToken },
      { ...BASE_OPTIONS, fetchImpl }
    );

    expect(calls).toHaveLength(1);
    expect(calls[0]!.url).toBe('https://api.line.me/v2/bot/message/push');
    expect(result.method).toBe('push');
    expect(guardHits).toBe(0);
  });

  it('a token with no recorded expiry is treated as valid (reply is attempted)', async () => {
    const { fetchImpl, calls } = createFetchMock([{ status: 200, body: {} }]);

    const result = await sendMessage(
      { userId: 'Uabc123', messages: 'hi', replyToken: 'reply-token-no-expiry', tokenExpires: null },
      { ...BASE_OPTIONS, fetchImpl }
    );

    expect(calls[0]!.url).toBe('https://api.line.me/v2/bot/message/reply');
    expect(result.method).toBe('reply');
  });

  describe('single-use token-clear callback — invoked exactly once, regardless of which reply-token branch is taken', () => {
    it.each([
      {
        branch: 'reply success',
        tokenExpires: () => futureBangkokDatetime(5 * 60_000),
        responses: [{ status: 200, body: {} }],
        expectedTransportCalls: 1,
      },
      {
        branch: 'reply failure (non-200)',
        tokenExpires: () => futureBangkokDatetime(5 * 60_000),
        responses: [
          { status: 500, body: {} },
          { status: 200, body: {} },
        ],
        expectedTransportCalls: 2,
      },
      {
        branch: 'expired token',
        tokenExpires: () => pastBangkokDatetime(60_000),
        responses: [{ status: 200, body: {} }],
        expectedTransportCalls: 1,
      },
    ])('$branch: onReplyTokenUsed called exactly once', async ({ tokenExpires, responses, expectedTransportCalls }) => {
      const { fetchImpl, calls } = createFetchMock(responses);
      const onReplyTokenUsed = vi.fn();

      await sendMessage(
        {
          userId: 'Uxyz789',
          messages: 'hi',
          replyToken: 'reply-token-under-test',
          tokenExpires: tokenExpires(),
          internalUserId: 7,
          onReplyTokenUsed,
        },
        { ...BASE_OPTIONS, fetchImpl }
      );

      expect(onReplyTokenUsed).toHaveBeenCalledTimes(1);
      expect(onReplyTokenUsed).toHaveBeenCalledWith({ lineUserId: 'Uxyz789', internalUserId: 7 });
      expect(calls).toHaveLength(expectedTransportCalls);
    });

    it('no reply token supplied: onReplyTokenUsed is never invoked (nothing to clear)', async () => {
      const { fetchImpl } = createFetchMock([{ status: 200, body: {} }]);
      const onReplyTokenUsed = vi.fn();

      await sendMessage(
        { userId: 'Uxyz789', messages: 'hi', replyToken: null, onReplyTokenUsed },
        { ...BASE_OPTIONS, fetchImpl }
      );

      expect(onReplyTokenUsed).not.toHaveBeenCalled();
    });

    it('omitting onReplyTokenUsed entirely does not throw, for every reply-token branch', async () => {
      const expired = createFetchMock([{ status: 200, body: {} }]);
      await expect(
        sendMessage(
          { userId: 'U1', messages: 'hi', replyToken: 'rt', tokenExpires: pastBangkokDatetime(1000) },
          { ...BASE_OPTIONS, fetchImpl: expired.fetchImpl }
        )
      ).resolves.toBeDefined();

      const success = createFetchMock([{ status: 200, body: {} }]);
      await expect(
        sendMessage(
          { userId: 'U1', messages: 'hi', replyToken: 'rt', tokenExpires: futureBangkokDatetime(60_000) },
          { ...BASE_OPTIONS, fetchImpl: success.fetchImpl }
        )
      ).resolves.toBeDefined();
    });
  });

  describe('message normalization (matches sendMessage()\'s $messages branching in classes/LineAPI.php:121-129)', () => {
    it('wraps a bare string into a single text message', async () => {
      const { fetchImpl, calls } = createFetchMock([{ status: 200, body: {} }]);
      await sendMessage({ userId: 'U1', messages: 'hello there' }, { ...BASE_OPTIONS, fetchImpl });
      const payload = JSON.parse(calls[0]!.init.body) as { to: string; messages: unknown };
      expect(payload.messages).toEqual([{ type: 'text', text: 'hello there' }]);
    });

    it('wraps a single message object (has "type") into a one-element array', async () => {
      const { fetchImpl, calls } = createFetchMock([{ status: 200, body: {} }]);
      const flexMessage = { type: 'flex', altText: 'label', contents: { type: 'bubble' } };
      await sendMessage({ userId: 'U1', messages: flexMessage }, { ...BASE_OPTIONS, fetchImpl });
      const payload = JSON.parse(calls[0]!.init.body) as { messages: unknown };
      expect(payload.messages).toEqual([flexMessage]);
    });

    it('passes an already-array list of messages through unchanged', async () => {
      const { fetchImpl, calls } = createFetchMock([{ status: 200, body: {} }]);
      const messages = [
        { type: 'text', text: 'one' },
        { type: 'text', text: 'two' },
      ];
      await sendMessage({ userId: 'U1', messages }, { ...BASE_OPTIONS, fetchImpl });
      const payload = JSON.parse(calls[0]!.init.body) as { messages: unknown };
      expect(payload.messages).toEqual(messages);
    });
  });
});

describe('replyMessage / pushMessage — classes/LineAPI.php:80-108', () => {
  it('replyMessage POSTs { replyToken, messages } to /message/reply with a Bearer auth header', async () => {
    const { fetchImpl, calls } = createFetchMock([{ status: 200, body: { sentMessages: [] } }]);
    const result = await replyMessage('rt-1', 'hi', { channelAccessToken: 'secret-token-value', fetchImpl });

    expect(calls).toHaveLength(1);
    expect(calls[0]!.url).toBe('https://api.line.me/v2/bot/message/reply');
    expect(calls[0]!.init.method).toBe('POST');
    expect(calls[0]!.init.headers).toMatchObject({
      'Content-Type': 'application/json',
      Authorization: 'Bearer secret-token-value',
    });
    expect(JSON.parse(calls[0]!.init.body)).toEqual({
      replyToken: 'rt-1',
      messages: [{ type: 'text', text: 'hi' }],
    });
    expect(result).toEqual({ code: 200, body: { sentMessages: [] } });
  });

  it('pushMessage POSTs { to, messages } to /message/push', async () => {
    const { fetchImpl, calls } = createFetchMock([{ status: 200, body: { sentMessages: [] } }]);
    const result = await pushMessage('U-target', ['already', 'an-array-placeholder'].map((t) => ({ type: 'text', text: t })), {
      channelAccessToken: 'tok',
      fetchImpl,
    });

    expect(calls[0]!.url).toBe('https://api.line.me/v2/bot/message/push');
    expect(JSON.parse(calls[0]!.init.body)).toEqual({
      to: 'U-target',
      messages: [
        { type: 'text', text: 'already' },
        { type: 'text', text: 'an-array-placeholder' },
      ],
    });
    expect(result.code).toBe(200);
  });

  it('respects an apiEndpoint override for both reply and push', async () => {
    const { fetchImpl, calls } = createFetchMock([
      { status: 200, body: {} },
      { status: 200, body: {} },
    ]);
    await replyMessage('rt', 'hi', { channelAccessToken: 'tok', apiEndpoint: 'https://example.test/bot', fetchImpl });
    await pushMessage('U1', 'hi', { channelAccessToken: 'tok', apiEndpoint: 'https://example.test/bot', fetchImpl });

    expect(calls[0]!.url).toBe('https://example.test/bot/message/reply');
    expect(calls[1]!.url).toBe('https://example.test/bot/message/push');
  });

  it('resolves with a null body (not a throw) when the response is not valid JSON', async () => {
    const fetchImpl: LineFetch = async () => ({
      status: 200,
      json: async () => {
        throw new SyntaxError('Unexpected end of JSON input');
      },
    });
    const result = await pushMessage('U1', 'hi', { channelAccessToken: 'tok', fetchImpl });
    expect(result).toEqual({ code: 200, body: null });
  });

  describe('a single message object passed directly is NOT array-wrapped (PHP is_array() pass-through)', () => {
    // classes/LineAPI.php:82-84 / 99-101: `if (!is_array($messages)) { wrap }` — a PHP
    // associative array (a single message hash) is already `is_array() === true`, so it is
    // passed straight through and json_encode()'s "messages" field is a JSON *object*, not a
    // one-element array. This is the exact call shape webhook.php:2051 uses today:
    //   $line->replyMessage($replyToken, ['type' => 'text', 'text' => '...']);
    // Only sendMessage() (classes/LineAPI.php:126-128, `isset($messages['type'])`) wraps a lone
    // object into a one-element array before ever calling replyMessage()/pushMessage() — see the
    // 'wraps a single message object ... into a one-element array' case in the sendMessage()
    // describe block above, which covers that (deliberately different) behavior.
    it('replyMessage: a single message object is sent unwrapped, matching webhook.php:2051', async () => {
      const { fetchImpl, calls } = createFetchMock([{ status: 200, body: {} }]);
      const singleMessage = { type: 'text', text: 'สวัสดีครับ' };
      await replyMessage('rt-1', singleMessage, { channelAccessToken: 'tok', fetchImpl });

      const payload = JSON.parse(calls[0]!.init.body) as { messages: unknown };
      expect(payload.messages).toEqual(singleMessage);
      expect(Array.isArray(payload.messages)).toBe(false);
    });

    it('pushMessage: a single message object is sent unwrapped', async () => {
      const { fetchImpl, calls } = createFetchMock([{ status: 200, body: {} }]);
      const singleMessage = { type: 'flex', altText: 'label', contents: { type: 'bubble' } };
      await pushMessage('U1', singleMessage, { channelAccessToken: 'tok', fetchImpl });

      const payload = JSON.parse(calls[0]!.init.body) as { messages: unknown };
      expect(payload.messages).toEqual(singleMessage);
      expect(Array.isArray(payload.messages)).toBe(false);
    });

    it('a bare string is still wrapped into a one-element text array (the one case PHP does wrap)', async () => {
      const { fetchImpl, calls } = createFetchMock([{ status: 200, body: {} }]);
      await replyMessage('rt-1', 'plain string', { channelAccessToken: 'tok', fetchImpl });

      const payload = JSON.parse(calls[0]!.init.body) as { messages: unknown };
      expect(payload.messages).toEqual([{ type: 'text', text: 'plain string' }]);
    });
  });
});

describe('multicastMessage / broadcastMessage — classes/LineAPI.php:219-241', () => {
  it('multicastMessage POSTs { to, messages } to /message/multicast with a Bearer auth header', async () => {
    const { fetchImpl, calls } = createFetchMock([{ status: 200, body: { sentMessages: [] } }]);
    const userIds = ['U1', 'U2', 'U3'];
    const result = await multicastMessage(userIds, 'hi everyone', { channelAccessToken: 'secret-token-value', fetchImpl });

    expect(calls).toHaveLength(1);
    expect(calls[0]!.url).toBe('https://api.line.me/v2/bot/message/multicast');
    expect(calls[0]!.init.method).toBe('POST');
    expect(calls[0]!.init.headers).toMatchObject({
      'Content-Type': 'application/json',
      Authorization: 'Bearer secret-token-value',
    });
    expect(JSON.parse(calls[0]!.init.body)).toEqual({
      to: userIds,
      messages: [{ type: 'text', text: 'hi everyone' }],
    });
    expect(result).toEqual({ code: 200, body: { sentMessages: [] } });
  });

  it('multicastMessage passes an array of message objects through unchanged', async () => {
    const { fetchImpl, calls } = createFetchMock([{ status: 200, body: {} }]);
    const messages = [
      { type: 'text', text: 'one' },
      { type: 'text', text: 'two' },
    ];
    await multicastMessage(['U1'], messages, { channelAccessToken: 'tok', fetchImpl });
    const payload = JSON.parse(calls[0]!.init.body) as { messages: unknown };
    expect(payload.messages).toEqual(messages);
  });

  it('multicastMessage sends a single message object unwrapped (PHP is_array() pass-through, matching pushMessage/replyMessage)', async () => {
    const { fetchImpl, calls } = createFetchMock([{ status: 200, body: {} }]);
    const singleMessage = { type: 'flex', altText: 'label', contents: { type: 'bubble' } };
    await multicastMessage(['U1', 'U2'], singleMessage, { channelAccessToken: 'tok', fetchImpl });
    const payload = JSON.parse(calls[0]!.init.body) as { messages: unknown; to: string[] };
    expect(payload.messages).toEqual(singleMessage);
    expect(Array.isArray(payload.messages)).toBe(false);
    expect(payload.to).toEqual(['U1', 'U2']);
  });

  it('multicastMessage propagates a non-200 LINE response code without throwing (caller decides sentCount accounting)', async () => {
    const { fetchImpl } = createFetchMock([{ status: 429, body: { message: 'rate limited' } }]);
    const result = await multicastMessage(['U1'], 'hi', { channelAccessToken: 'tok', fetchImpl });
    expect(result).toEqual({ code: 429, body: { message: 'rate limited' } });
  });

  it('broadcastMessage POSTs { messages } (no "to" field) to /message/broadcast', async () => {
    const { fetchImpl, calls } = createFetchMock([{ status: 200, body: { sentMessages: [] } }]);
    const result = await broadcastMessage('hello everyone', { channelAccessToken: 'secret-token-value', fetchImpl });

    expect(calls).toHaveLength(1);
    expect(calls[0]!.url).toBe('https://api.line.me/v2/bot/message/broadcast');
    expect(calls[0]!.init.method).toBe('POST');
    const payload = JSON.parse(calls[0]!.init.body) as Record<string, unknown>;
    expect(payload).toEqual({ messages: [{ type: 'text', text: 'hello everyone' }] });
    expect('to' in payload).toBe(false);
    expect(result).toEqual({ code: 200, body: { sentMessages: [] } });
  });

  it('broadcastMessage sends a single message object unwrapped, an array of messages unchanged, and respects apiEndpoint override', async () => {
    const { fetchImpl, calls } = createFetchMock([
      { status: 200, body: {} },
      { status: 200, body: {} },
      { status: 200, body: {} },
    ]);
    const singleMessage = { type: 'image', originalContentUrl: 'https://x/img.jpg', previewImageUrl: 'https://x/img.jpg' };
    await broadcastMessage(singleMessage, { channelAccessToken: 'tok', fetchImpl });
    const arrayMessages = [{ type: 'text', text: 'a' }, { type: 'text', text: 'b' }];
    await broadcastMessage(arrayMessages, { channelAccessToken: 'tok', fetchImpl });
    await broadcastMessage('hi', { channelAccessToken: 'tok', apiEndpoint: 'https://example.test/bot', fetchImpl });

    expect(JSON.parse(calls[0]!.init.body)).toEqual({ messages: singleMessage });
    expect(Array.isArray((JSON.parse(calls[0]!.init.body) as { messages: unknown }).messages)).toBe(false);
    expect(JSON.parse(calls[1]!.init.body)).toEqual({ messages: arrayMessages });
    expect(calls[2]!.url).toBe('https://example.test/bot/message/broadcast');
  });

  it('resolves with a null body (not a throw) when the response is not valid JSON, for both multicastMessage and broadcastMessage', async () => {
    const notJsonFetch: LineFetch = async () => ({
      status: 200,
      json: async () => {
        throw new SyntaxError('Unexpected end of JSON input');
      },
    });
    expect(await multicastMessage(['U1'], 'hi', { channelAccessToken: 'tok', fetchImpl: notJsonFetch })).toEqual({
      code: 200,
      body: null,
    });
    expect(await broadcastMessage('hi', { channelAccessToken: 'tok', fetchImpl: notJsonFetch })).toEqual({
      code: 200,
      body: null,
    });
  });

  it('delegates to the runtime global fetch when fetchImpl is omitted for both functions (real transport, not stubbed)', async () => {
    const globalFetchMock = vi.fn(async (_url: string, _init: unknown) => ({
      status: 200,
      json: async () => ({ sentMessages: [] }),
    }));
    vi.stubGlobal('fetch', globalFetchMock);
    try {
      await multicastMessage(['U1'], 'hi', { channelAccessToken: 'token-abc' });
      await broadcastMessage('hi', { channelAccessToken: 'token-abc' });
      expect(globalFetchMock).toHaveBeenCalledTimes(2);
      expect(globalFetchMock.mock.calls[0]?.[0]).toBe('https://api.line.me/v2/bot/message/multicast');
      expect(globalFetchMock.mock.calls[1]?.[0]).toBe('https://api.line.me/v2/bot/message/broadcast');
    } finally {
      vi.unstubAllGlobals();
    }
  });
});

describe('default transport wiring — no fetchImpl override supplied', () => {
  afterEach(() => {
    vi.unstubAllGlobals();
  });

  it('delegates to the runtime global fetch when fetchImpl is omitted (the real transport is implemented, not stubbed out)', async () => {
    const globalFetchMock = vi.fn(async (_url: string, _init: unknown) => ({
      status: 200,
      json: async () => ({ sentMessages: [] }),
    }));
    vi.stubGlobal('fetch', globalFetchMock);

    const result = await replyMessage('reply-token-xyz', 'hello', { channelAccessToken: 'token-abc' });

    expect(globalFetchMock).toHaveBeenCalledTimes(1);
    expect(globalFetchMock.mock.calls[0]?.[0]).toBe('https://api.line.me/v2/bot/message/reply');
    expect(result).toEqual({ code: 200, body: { sentMessages: [] } });
  });

  it('throws a clear, actionable error instead of crashing cryptically when no fetch exists at all', async () => {
    vi.stubGlobal('fetch', undefined);
    await expect(replyMessage('rt', 'hi', { channelAccessToken: 'token-abc' })).rejects.toThrow(
      /global fetch is unavailable/
    );
  });
});
